require __DIR__.'/../../app/bootstrap.php';require_once __DIR__.'/../../app/api_v2.php';$u=api_v2_user('orders');$uid=(int)$u['user_id'];[$page,$per,$off]=api_v2_page();$cnt=db()->prepare('SELECT COUNT(*) FROM store_orders WHERE buyer_user_id=?');$cnt->execute([$uid]);$total=(int)$cnt->fetchColumn();$q=db()->prepare("SELECT o.id,o.order_number,o.grand_total,o.payment_method,o.payment_status,o.status,o.created_at,u.name seller_name,(SELECT COUNT(*) FROM store_order_items oi WHERE oi.order_id=o.id) item_count FROM store_orders o JOIN users u ON u.id=o.seller_user_id WHERE o.buyer_user_id=? ORDER BY o.id DESC LIMIT {$per} OFFSET {$off}");$q->execute([$uid]);api_v2_ok(['orders'=>$q->fetchAll(),'meta'=>api_v2_meta($page,$per,$total)],$uid);
